var OutputSplatDepth = class extends Dyno {
	constructor({ gsplat, viewCenter, viewDir, sortRadial }) {
		super({
			inTypes: {
				gsplat: Gsplat,
				viewCenter: "vec3",
				viewDir: "vec3",
				sortRadial: "bool"
			},
			inputs: {
				gsplat,
				viewCenter,
				viewDir,
				sortRadial
			},
			globals: () => [defineGsplat],
			statements: ({ inputs }) => {
				const { gsplat, viewCenter, viewDir, sortRadial } = inputs;
				if (gsplat && viewCenter && viewDir && sortRadial) return unindentLines(`
            float metric = 1.0 / 0.0;
            if (isGsplatActive(${gsplat}.flags)) {
              vec3 center = ${gsplat}.center - ${viewCenter};
              if (${sortRadial}) {
                metric = length(center);
              } else {
                float bias = 100.0; // reduce popping
                metric = dot(center, ${viewDir}) + bias;
              }
            }
            target3 = floatToVec4(metric);
          `);
				return [];
			}
		});
	}
};
