	if (type === "mat2x3") return "mat3x2";
	if (type === "mat2x4") return "mat4x2";
	if (type === "mat3x2") return "mat2x3";
	if (type === "mat3x3") return "mat3x3";
	if (type === "mat3x4") return "mat4x3";
	if (type === "mat4x2") return "mat2x4";
