var TransformPosition = class extends Dyno {
	constructor({ position, scale, scales, rotate, translate }) {
		super({
			inTypes: {
				position: "vec3",
				scale: "float",
				scales: "vec3",
				rotate: "vec4",
				translate: "vec3"
			},
			outTypes: { position: "vec3" },
			inputs: {
				position,
				scale,
				scales,
				rotate,
				translate
			},
			statements: ({ inputs, outputs }) => {
				const { position } = outputs;
				if (!position) return [];
				const { scale, scales, rotate, translate } = inputs;
				return [
					`${position} = ${inputs.position ?? "vec3(0.0, 0.0, 0.0)"};`,
					!scale ? null : `${position} *= ${scale};`,
					!scales ? null : `${position} *= ${scales};`,
					!rotate ? null : `${position} = quatVec(${rotate}, ${position});`,
					!translate ? null : `${position} += ${translate};`
				].filter(Boolean);
			}
		});
	}
};
var TransformDir = class extends Dyno {
	constructor({ dir, scale, scales, rotate }) {
		super({
			inTypes: {
				dir: "vec3",
				scale: "float",
				scales: "vec3",
				rotate: "vec4"
			},
			outTypes: { dir: "vec3" },
			inputs: {
				dir,
				scale,
				scales,
				rotate
			},
			statements: ({ inputs, outputs }) => {
				const { dir } = outputs;
				if (!dir) return [];
				const { scale, scales, rotate } = inputs;
				return [
					`${dir} = ${inputs.dir ?? "vec3(0.0, 0.0, 0.0)"};`,
					!scale ? null : `${dir} *= ${scale};`,
					!scales ? null : `${dir} *= ${scales};`,
					!rotate ? null : `${dir} = quatVec(${rotate}, ${dir});`
				].filter(Boolean);
			}
		});
	}
};
var TransformQuaternion = class extends Dyno {
	constructor({ quaternion, rotate }) {
		super({
			inTypes: {
				quaternion: "vec4",
				rotate: "vec4"
			},
			outTypes: { quaternion: "vec4" },
			inputs: {
				quaternion,
				rotate
			},
			statements: ({ inputs, outputs }) => {
				const { quaternion } = outputs;
				if (!quaternion) return [];
				return [`${quaternion} = ${inputs.quaternion ?? "vec4(0.0, 0.0, 0.0, 1.0)"};`, !rotate ? null : `${quaternion} = quatQuat(${inputs.rotate}, ${quaternion});`].filter(Boolean);
			}
		});
	}
};
