function textureSizeType(textureType) {
	switch (textureType) {
		case "sampler2D":
		case "usampler2D":
		case "isampler2D":
		case "samplerCube":
		case "usamplerCube":
		case "isamplerCube":
		case "sampler2DShadow":
		case "samplerCubeShadow": return "ivec2";
		case "sampler3D":
		case "usampler3D":
		case "isampler3D":
		case "sampler2DArray":
		case "usampler2DArray":
		case "isampler2DArray":
		case "sampler2DArrayShadow": return "ivec3";
		default: throw new Error(`Invalid texture type: ${textureType}`);
	}
}
function textureCoordType(textureType) {
	switch (textureType) {
		case "sampler2D":
		case "usampler2D":
		case "isampler2D": return "vec2";
		case "sampler3D":
		case "usampler3D":
		case "isampler3D":
		case "samplerCube":
		case "usamplerCube":
		case "isamplerCube":
		case "sampler2DArray":
		case "usampler2DArray":
		case "isampler2DArray":
		case "sampler2DShadow": return "vec3";
		case "samplerCubeShadow":
		case "sampler2DArrayShadow": return "vec4";
		default: throw new Error(`Invalid texture type: ${textureType}`);
	}
}
function textureReturnType(textureType) {
	switch (textureType) {
		case "sampler2D":
		case "sampler2DArray":
		case "sampler3D":
		case "samplerCube":
		case "sampler2DShadow": return "vec4";
		case "usampler2D":
		case "usampler2DArray":
		case "usampler3D":
		case "usamplerCube": return "uvec4";
		case "isampler2D":
		case "isampler2DArray":
		case "isampler3D":
		case "isamplerCube": return "ivec4";
		case "samplerCubeShadow":
		case "sampler2DArrayShadow": return "float";
		default: throw new Error(`Invalid texture type: ${textureType}`);
	}
}
